function getProductNames(products) {
  return products.map(product => product.name);
}

function getAvailableProducts(products, category) {
  return products.filter(
    product => product.category === category && product.inStock
  );
}

function getTotalInventoryValue(products) {
  return products
    .filter(product => product.inStock)
    .reduce((total, product) => total + product.price, 0);
}

function findMostExpensive(products) {
  return products.reduce((max, product) =>
    product.price > max.price ? product : max
  );
}

function areAllInStock(products, category) {
  const categoryProducts = products.filter(p => p.category === category);
  return categoryProducts.every(product => product.inStock);
}

console.log(getProductNames(products));
console.log(getAvailableProducts(products, "electronics"));
console.log(getTotalInventoryValue(products));
console.log(findMostExpensive(products));
console.log(areAllInStock(products, "electronics"));
